/* =========================================
   0. 隐藏 AI 的剧情设定标签
========================================= */
World, secret {
    display: none; 
}

/* =========================================
   1. 微信主容器
========================================= */
.wechat {
    width: 375px;           
    height: 600px;          
    background-color: #ffffff; 
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    border-radius: 12px;    
    border: 1px solid #888888; 
    box-shadow: 0 10px 30px rgba(0,0,0,0.1); 
    position: relative;
    margin: 40px auto;      
    overflow: hidden; 
}

/* =========================================
   2. 顶部导航栏
========================================= */
chatname {
    position: absolute;       
    top: 0;
    left: 0;
    z-index: 10;
    display: block;
    width: 100%;
    height: 50px;
    line-height: 50px;
    text-align: center;     
    font-size: 17px;
    font-weight: 500;
    color: #000000;
    background-color: #ffffff; 
    border-bottom: 1px solid #e0e0e0; 
}

chatname::before {
    content: '';
    position: absolute;
    left: 20px;
    top: 17px;
    width: 12px;
    height: 12px;
    border-left: 2px solid #888888; 
    border-bottom: 2px solid #888888; 
    transform: rotate(45deg); 
}

chatname::after {
    content: '';
    position: absolute;
    right: 25px; 
    top: 23px;
    width: 4px;
    height: 4px;
    background-color: #888888; 
    border-radius: 50%;
    box-shadow: -7px 0 0 #888888, 7px 0 0 #888888; 
}

/* =========================================
   3. 聊天消息区基础设置
========================================= */
msg {
    display: block;
    width: 100%;
    height: calc(100% - 106px); 
    margin-top: 50px; 
    overflow-y: auto;
    background-color: #ededed; 
    padding-top: 15px;
    padding-bottom: 20px;
}

msg::-webkit-scrollbar {
    display: none; 
}

sysmsg {
    display: block;
    text-align: center;
    font-size: 12px;
    color: #b2b2b2;
    margin: 10px 0 20px 0;
}

/* =========================================
   4. 对方发言 (左侧，白色气泡 + 名字) - UIA
========================================= */
UIA {
    display: grid;
    grid-template-columns: 40px 1fr; /* 左侧头像固定40px，右侧名字和气泡自适应 */
    grid-template-rows: auto auto;   /* 第一行为名字，第二行为气泡 */
    column-gap: 12px;
    row-gap: 4px; /* 名字和气泡的上下间距 */
    padding: 0 15px;
    margin-bottom: 15px;
}

UIA img {
    grid-column: 1;
    grid-row: 1 / 3; /* 头像独占左侧，高度跨越名字和气泡两行 */
    width: 40px;
    height: 40px;
    border-radius: 4px; 
    object-fit: cover; 
    background-color: #ffffff; 
}

UIA name {
    grid-column: 2;
    grid-row: 1; /* 名字在第一行 */
    font-size: 12px;
    color: #888888; /* 灰色小号字体 */
    line-height: 1;
    margin-top: 2px; /* 与头像顶部平齐 */
}

UIA span {
    grid-column: 2;
    grid-row: 2; /* 气泡在第二行（被名字压在下面，绝不会高过头像） */
    justify-self: start; /* 气泡靠左对齐，不自动拉伸 */
    background-color: #ffffff;
    color: #333333;
    font-size: 15px;
    padding: 10px 14px;
    border-radius: 6px;
    line-height: 1.5;
    max-width: 85%; 
    word-break: break-all;
    position: relative;
    box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

/* 左侧气泡小三角 */
UIA span::before {
    content: '';
    position: absolute;
    left: -6px;
    top: 10px; /* 小角精准指向头像中部 */
    border-top: 5px solid transparent;
    border-bottom: 5px solid transparent;
    border-right: 6px solid #ffffff;
}

/* =========================================
   5. 玩家发言 (右侧，绿色气泡 + 名字) - UIB
========================================= */
UIB {
    display: grid;
    grid-template-columns: 1fr 40px; /* 文字在左侧自适应，头像在右侧固定40px */
    grid-template-rows: auto auto; 
    column-gap: 12px;
    row-gap: 4px; 
    padding: 0 15px;
    margin-bottom: 15px;
}

UIB img {
    grid-column: 2;
    grid-row: 1 / 3; /* 头像在最右侧跨越两行 */
    width: 40px;
    height: 40px;
    border-radius: 4px; 
    object-fit: cover; 
    background-color: #ffffff; 
}

UIB name {
    grid-column: 1;
    grid-row: 1;
    justify-self: end; /* 名字靠右对齐 */
    font-size: 12px;
    color: #888888; 
    line-height: 1;
    margin-top: 2px;
}

UIB span {
    grid-column: 1;
    grid-row: 2;
    justify-self: end; /* 气泡靠右对齐 */
    background-color: #95ec69; /* 微信经典绿 */
    color: #333333;
    font-size: 15px;
    padding: 10px 14px;
    border-radius: 6px;
    line-height: 1.5;
    max-width: 85%; 
    word-break: break-all;
    position: relative;
    box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

/* 右侧气泡小三角 (绿色) */
UIB span::before {
    content: '';
    position: absolute;
    right: -6px; 
    top: 10px;
    border-top: 5px solid transparent;
    border-bottom: 5px solid transparent;
    border-left: 6px solid #95ec69; 
}

/* =========================================
   6. 底部输入栏
========================================= */
